const letterLabels = ["أ", "ب", "ج", "د"];

function Logo({ compact = false }: { compact?: boolean }) {
  return <div className={`brand ${compact ? "brand--compact" : ""}`}><span className="brand-mark"><span /></span><span className="brand-type">IQ <b>ARENA</b></span></div>;
}

function Button({ children, onClick, variant = "primary", className = "" }: { children: ReactNode; onClick?: () => void; variant?: "primary" | "ghost" | "light"; className?: string }) {
  return <button type="button" onClick={onClick} className={`button button--${variant} ${className}`}>{children}</button>;
}

function RingIcon({ number, active, done }: { number: number; active?: boolean; done?: boolean }) {
  return <span className={`step-ring ${active ? "is-active" : ""} ${done ? "is-done" : ""}`}>{done ? <Check size={14} strokeWidth={3} /> : number}</span>;
}

function QuestionVisual({ question }: { question: Question }) {
  if (question.visual === "numbers") return <div className="visual-sequence" aria-label="تسلسل عددي">{question.visualData?.map((item, index) => <span key={index} className={item === "?" ? "sequence-question" : ""}>{item}</span>)}</div>;
  if (question.visual === "shape-sequence") return <div className="shape-sequence" aria-label="تسلسل أشكال">{question.visualData?.map((shape, index) => shape === "?" ? <span key={index} className="shape-tile shape-tile--question">?</span> : <span key={index} className={`shape-tile shape-tile--${shape}`} />)}</div>;
  if (question.visual === "matrix") return <div className="matrix-board" aria-label="مصفوفة منطقية"><div className="matrix-cell"><span className="matrix-circle" /></div><div className="matrix-cell"><span className="matrix-circle matrix-circle--split" /></div><div className="matrix-cell"><span className="matrix-triangle" /></div><div className="matrix-cell matrix-cell--missing">?</div></div>;
  if (question.visual === "odd-one-out") return <div className="odd-board" aria-label="بطاقات لاكتشاف المختلف">{[0, 1, 2, 3].map((item) => <div key={item} className={`odd-card odd-card--${item}`}><span /></div>)}</div>;
  if (question.visual === "rotation") return <div className="rotation-board" aria-label="دوران سهم"><div className="rotation-arrow">➜</div><div className="rotation-orbit"><span>0°</span><span>90°</span><span>180°</span><span>270°</span></div></div>;
  if (question.visual === "arithmetic") return <div className="arithmetic-board" aria-label="مصفوفة حسابية">{question.visualData?.map((row, index) => <div key={index} className="arithmetic-row"><span>{row}</span>{index < 2 ? <Check size={15} /> : <span className="arithmetic-missing">؟</span>}</div>)}</div>;
  return <div className="symbol-board" aria-label="تتابع رموز">{question.visualData?.map((item, index) => <span key={index} className={item === "؟" || item === "?" ? "symbol-missing" : index % 2 === 0 ? "symbol-cyan" : "symbol-amber"}>{item}</span>)}</div>;
}

function HeroVisual() {
  return <div className="hero-visual" aria-hidden="true"><div className="hero-orbit hero-orbit--one" /><div className="hero-orbit hero-orbit--two" /><div className="hero-glow" /><div className="hero-grid" /><div className="preview-card"><div className="preview-card__top"><span>سؤال 07 / 12</span><span className="preview-live"><i /> مباشر</span></div><div className="preview-progress"><span /></div><div className="preview-pattern"><span className="pattern-circle" /><span className="pattern-half" /><span className="pattern-triangle" /><span className="pattern-diamond" /><span className="pattern-question">?</span></div><p>ما الشكل التالي في النمط؟</p><div className="preview-options"><span>أ</span><span>ب</span><span className="is-active">ج</span><span>د</span></div></div><div className="float-chip float-chip--top"><Zap size={14} /> سرعة التفكير</div><div className="float-chip float-chip--bottom"><Target size={14} /> 8.7 / 10 دقة</div></div>;
}

type GameSettings = {
  questionCount: 10 | 12 | 15;
  timeMode: 20 | 30 | 45;
  difficulty: "all" | "balanced" | "advanced";
  sound: boolean;
  motion: boolean;
  saveProgress: boolean;
};

type PlayerProfile = { name: string; age: string };
const defaultSettings: GameSettings = { questionCount: 12, timeMode: 30, difficulty: "all", sound: true, motion: true, saveProgress: true };
const defaultProfile: PlayerProfile = { name: "", age: "" };

function shuffle<T>(items: T[]): T[] {
  const copy = [...items];
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [copy[index], copy[swapIndex]] = [copy[swapIndex], copy[index]];
  }
  return copy;
}

function SettingsPanel({ profile, settings, onSave, onClose }: { profile: PlayerProfile; settings: GameSettings; onSave: (profile: PlayerProfile, settings: GameSettings) => void; onClose: () => void }) {
  const [draftProfile, setDraftProfile] = useState(profile);
  const [draftSettings, setDraftSettings] = useState(settings);
  const setSetting = <K extends keyof GameSettings>(key: K, value: GameSettings[K]) => setDraftSettings((current) => ({ ...current, [key]: value }));
  return <div className="settings-backdrop" role="dialog" aria-modal="true" aria-label="إعدادات اللعبة"><div className="settings-panel"><div className="settings-head"><div><span className="section-kicker">تخصيص التجربة</span><h2>إعداداتك الذكية</h2><p>احفظ تفضيلاتك واجعل كل جلسة مناسبة لك.</p></div><button className="close-button" onClick={onClose} aria-label="إغلاق"><X size={18} /></button></div><div className="profile-fields"><label><span><UserRound size={14} /> الاسم</span><input value={draftProfile.name} onChange={(event) => setDraftProfile({ ...draftProfile, name: event.target.value })} placeholder="مثال: أحمد" maxLength={24} /></label><label><span>العمر <small>اختياري</small></span><input inputMode="numeric" value={draftProfile.age} onChange={(event) => setDraftProfile({ ...draftProfile, age: event.target.value.replace(/\D/g, "").slice(0, 3) })} placeholder="25" /></label></div><div className="settings-group"><span className="settings-label">عدد الأسئلة</span><div className="segmented">{([10, 12, 15] as const).map((count) => <button key={count} className={draftSettings.questionCount === count ? "is-selected" : ""} onClick={() => setSetting("questionCount", count)}>{count} سؤال</button>)}</div></div><div className="settings-group"><span className="settings-label">زمن السؤال</span><div className="segmented">{([20, 30, 45] as const).map((seconds) => <button key={seconds} className={draftSettings.timeMode === seconds ? "is-selected" : ""} onClick={() => setSetting("timeMode", seconds)}>{seconds} ثانية</button>)}</div></div><div className="settings-group"><span className="settings-label">مستوى التحدي</span><div className="segmented segmented--wide"><button className={draftSettings.difficulty === "all" ? "is-selected" : ""} onClick={() => setSetting("difficulty", "all")}>متنوع</button><button className={draftSettings.difficulty === "balanced" ? "is-selected" : ""} onClick={() => setSetting("difficulty", "balanced")}>متوازن</button><button className={draftSettings.difficulty === "advanced" ? "is-selected" : ""} onClick={() => setSetting("difficulty", "advanced")}>متقدم</button></div></div><div className="toggle-list"><button onClick={() => setSetting("sound", !draftSettings.sound)}><span className="toggle-icon">{draftSettings.sound ? <Volume2 size={15} /> : <VolumeX size={15} />}</span><span><b>مؤثرات صوتية</b><small>تنبيهات خفيفة عند الإجابة</small></span><i className={draftSettings.sound ? "is-on" : ""} /></button><button onClick={() => setSetting("motion", !draftSettings.motion)}><span className="toggle-icon"><Sparkles size={15} /></span><span><b>حركة واجهة هادئة</b><small>حركات انتقالية محسوبة</small></span><i className={draftSettings.motion ? "is-on" : ""} /></button><button onClick={() => setSetting("saveProgress", !draftSettings.saveProgress)}><span className="toggle-icon"><Target size={15} /></span><span><b>حفظ التفضيلات</b><small>تذكر اسمك وإعداداتك على هذا الجهاز</small></span><i className={draftSettings.saveProgress ? "is-on" : ""} /></button></div><div className="settings-actions"><Button variant="ghost" onClick={onClose}>إلغاء</Button><Button onClick={() => onSave(draftProfile, draftSettings)}><Check size={16} /> حفظ وبدء الاختبار</Button></div></div></div>;
}

function Landing({ profile, settings, onStart, onOpenSettings }: { profile: PlayerProfile; settings: GameSettings; onStart: () => void; onOpenSettings: () => void }) {
  return <main className="landing-shell"><nav className="top-nav container"><Logo /><div className="nav-meta"><span className="profile-pill"><UserRound size={14} /> {profile.name || "ضيف"}{profile.age ? ` · ${profile.age}` : ""}</span><button className="settings-trigger" onClick={onOpenSettings}><Settings size={15} /> الإعدادات</button></div></nav><section className="hero container"><div className="hero-copy"><div className="eyebrow"><Sparkles size={15} /> اختبار ذكي، مصمم لعقلك</div><h1>اكتشف <em>قوة تفكيرك</em><br />في {settings.questionCount} سؤالًا.</h1><p className="hero-lede">رحلة قصيرة تكشف طريقة تفكيرك عبر أنماط بصرية، منطق، أرقام، وسرعة بديهة. بنك أسئلة متجدد يختار لك تحديًا مختلفًا في كل مرة.</p><div className="hero-actions"><Button onClick={onStart} className="button--hero"><Play size={18} fill="currentColor" /> ابدأ اختبار الذكاء <ArrowLeft size={18} /></Button><span className="hero-time"><Clock3 size={16} /> {settings.timeMode} ثانية لكل سؤال</span></div><div className="trust-row"><div className="avatars"><span>س</span><span>م</span><span>ر</span><span>+</span></div><span><b>108 أسئلة أصلية</b> · ترتيب عشوائي بلا تكرار داخل الجلسة</span></div></div><HeroVisual /></section><section className="feature-strip container"><div className="feature-item"><span className="feature-icon feature-icon--cyan"><Layers3 size={18} /></span><span><b>بنك أسئلة متجدد</b><small>تشكيلة مختلفة في كل جلسة</small></span></div><div className="feature-item"><span className="feature-icon feature-icon--amber"><TimerReset size={18} /></span><span><b>تحكم كامل بالوقت</b><small>20 أو 30 أو 45 ثانية</small></span></div><div className="feature-item"><span className="feature-icon feature-icon--violet"><Crown size={18} /></span><span><b>ملف شخصي وتحليل</b><small>نتيجة تحمل اسمك وتفضيلاتك</small></span></div></section><footer className="landing-footer container"><span>IQ ARENA <i>•</i> تحدٍ لعقلك، لا لوقتك</span><span className="footer-key"><Keyboard size={14} /> يمكنك استخدام 1–4 للإجابة</span></footer></main>;
}

function Quiz({ session, profile, settings, onFinish }: { session: Question[]; profile: PlayerProfile; settings: GameSettings; onFinish: (score: number, answers: number[], elapsed: number) => void }) {
  const [current, setCurrent] = useState(0);
  const [answers, setAnswers] = useState<number[]>([]);
  const [selected, setSelected] = useState<number | null>(null);
  const [timeLeft, setTimeLeft] = useState<number>(settings.timeMode);
  const [startedAt] = useState(() => Date.now());
  const question = session[current];
  const progress = ((current + (selected !== null ? 1 : 0)) / session.length) * 100;
  const advance = useCallback((answer: number) => {
    if (selected !== null) return;
    setSelected(answer);
    const nextAnswers = [...answers, answer];
    window.setTimeout(() => {
      if (current === session.length - 1) {
        const score = nextAnswers.reduce((total, item, index) => total + (item === session[index].answer ? 1 : 0), 0);
        onFinish(score, nextAnswers, Math.round((Date.now() - startedAt) / 1000));
      } else {
        setAnswers(nextAnswers); setCurrent((value) => value + 1); setSelected(null); setTimeLeft(settings.timeMode);
      }
    }, settings.motion ? 520 : 100);
  }, [answers, current, onFinish, selected, session, settings.motion, settings.timeMode, startedAt]);
  useEffect(() => { if (selected !== null) return; const timer = window.setInterval(() => setTimeLeft((value) => { if (value <= 1) { window.clearInterval(timer); advance(-1); return 0; } return (value - 1) as GameSettings["timeMode"]; }), 1000); return () => window.clearInterval(timer); }, [advance, selected]);
  useEffect(() => { const onKeyDown = (event: KeyboardEvent) => { const key = Number(event.key); if (key >= 1 && key <= 4) advance(key - 1); }; window.addEventListener("keydown", onKeyDown); return () => window.removeEventListener("keydown", onKeyDown); }, [advance]);
  return <main className="quiz-shell"><nav className="quiz-nav container"><Logo compact /><div className="quiz-nav-center"><span>{profile.name ? `اختبار ${profile.name}` : "اختبار الذكاء"}</span><span className="nav-divider" /><span>{settings.difficulty === "all" ? "تحدٍ متنوع" : settings.difficulty === "advanced" ? "وضع متقدم" : "وضع متوازن"}</span></div><div className="quiz-timer"><Clock3 size={16} /><span>00:{String(timeLeft).padStart(2, "0")}</span></div></nav><section className="quiz-layout container"><div className="quiz-main"><div className="quiz-progress-row"><div className="quiz-progress"><span style={{ width: `${Math.max(progress, (current / session.length) * 100)}%` }} /></div><span><b>{String(current + 1).padStart(2, "0")}</b> / {String(session.length).padStart(2, "0")}</span></div><div className="question-heading"><div className="question-meta"><span className="category-dot" /> {question.category} <span className={`difficulty difficulty--${question.difficulty}`}>{question.difficulty}</span></div><h2>{question.prompt}</h2><p>{question.subprompt}</p></div><div className="question-visual-card"><QuestionVisual question={question} /></div><div className="answers-grid">{question.options.map((option, index) => <button key={option} className={`answer-card ${selected === index ? (index === question.answer ? "is-correct" : "is-wrong") : ""} ${selected !== null && index === question.answer ? "show-correct" : ""}`} onClick={() => advance(index)} disabled={selected !== null} aria-label={`الإجابة ${letterLabels[index]}: ${option}`}><span className="answer-letter">{letterLabels[index]}</span><span className="answer-text">{option}</span><span className="answer-indicator">{selected !== null && index === question.answer ? <Check size={16} /> : selected === index && index !== question.answer ? <X size={16} /> : <ArrowLeft size={16} />}</span></button>)}</div><div className="quiz-hint"><Keyboard size={15} /> اختر إجابتك باستخدام الأرقام <b>1</b>–<b>4</b><span>•</span><span>{settings.sound ? "صوت الإشعارات مفعّل" : "الوضع الصامت"}</span></div></div><aside className="quiz-side"><div className="side-card side-card--score"><div className="side-card__top"><span>مؤشر التقدم</span><span className="live-badge"><i /> {profile.name || "مباشر"}</span></div><div className="steps-grid">{session.map((item, index) => <RingIcon key={item.id} number={index + 1} active={index === current} done={index < current} />)}</div><div className="side-divider" /><div className="side-stat"><span>المجال الحالي</span><b>{question.label}</b></div></div><div className="side-card side-card--tip"><Lightbulb size={19} /><div><b>تلميح سريع</b><p>لا تبحث عن الكمال. الاختبار يقيس كيف توازن بين السرعة والدقة.</p></div></div><div className="side-foot"><Sparkles size={14} /> جلسة جديدة · {session.length} أسئلة</div></aside></section></main>;
}

function Result({ score, elapsed, profile, sessionLength, onRestart }: { score: number; answers: number[]; elapsed: number; profile: PlayerProfile; sessionLength: number; onRestart: () => void }) {
  const percentage = Math.round((score / sessionLength) * 100); const iq = Math.min(145, Math.max(82, 86 + score * 4 + (elapsed < sessionLength * 26 ? 4 : 0))); const label = iq >= 125 ? "استثنائي" : iq >= 110 ? "متقدم" : iq >= 90 ? "متوازن" : "قابل للتطور";
  const breakdown = useMemo(() => ["المنطق", "الأنماط", "السرعة"].map((group, index) => ({ group, value: Math.min(98, Math.max(42, percentage + [7, -4, elapsed < sessionLength * 26 ? 9 : -2][index])) })), [elapsed, percentage, sessionLength]);
  const share = async () => { const text = `${profile.name || "صديقي"} حصل على ${iq} في اختبار IQ Arena — ${label}`; if (navigator.share) await navigator.share({ title: "نتيجتي في IQ Arena", text }); else await navigator.clipboard?.writeText(text); };
  return <main className="result-shell"><nav className="top-nav container"><Logo /><span className="result-nav-note"><Check size={15} /> أحسنت {profile.name || "أيها المستكشف"} · اكتمل الاختبار</span></nav><section className="result-layout container"><div className="result-intro"><div className="eyebrow"><Trophy size={15} /> النتيجة جاهزة</div><h1>هذه هي <em>بصمتك الذهنية.</em></h1><p>أجبت عن {score} من {sessionLength} أسئلة بشكل صحيح. النتيجة تعكس أداءك في هذا التحدي وليست تشخيصًا طبيًا.</p><div className="result-actions"><Button onClick={share} variant="light"><Share2 size={17} /> مشاركة النتيجة</Button><Button onClick={onRestart} variant="ghost"><RotateCcw size={17} /> جلسة جديدة</Button></div></div><div className="result-score-card"><div className="score-orbit score-orbit--one" /><div className="score-orbit score-orbit--two" /><div className="score-kicker">مؤشر IQ التقريبي</div><div className="score-number">{iq}</div><div className="score-label"><span /> {label}</div><div className="score-scale"><span>80</span><div><i style={{ width: `${Math.min(100, ((iq - 80) / 65) * 100)}%` }} /></div><span>145</span></div></div></section><section className="result-details container"><div className="detail-card detail-card--breakdown"><div className="detail-head"><div><span className="section-kicker">تحليل الأداء</span><h2>كيف تفكر؟</h2></div><span className="detail-count">{percentage}% دقة</span></div>{breakdown.map((item) => <div key={item.group} className="breakdown-row"><div className="breakdown-label"><span>{item.group}</span><b>{item.value}%</b></div><div className="breakdown-track"><i style={{ width: `${item.value}%` }} /></div></div>)}</div><div className="detail-card detail-card--summary"><div className="section-kicker">ملخص سريع</div><div className="summary-list"><div><span className="summary-icon summary-icon--cyan"><Check size={15} /></span><span><b>{score} إجابات صحيحة</b><small>قدرة جيدة على اكتشاف القواعد</small></span></div><div><span className="summary-icon summary-icon--amber"><Zap size={15} /></span><span><b>{elapsed} ثانية</b><small>زمن الجلسة الكلي</small></span></div><div><span className="summary-icon summary-icon--violet"><Brain size={15} /></span><span><b>بنك متجدد</b><small>ستحصل على أسئلة مختلفة في الجلسة القادمة</small></span></div></div></div></section><footer className="result-footer container"><span>IQ ARENA <i>•</i> صمّم لقياس فضولك</span><span>نتيجتك محفوظة على جهازك فقط</span></footer></main>;
}

export default function Home() {
  const [screen, setScreen] = useState<"landing" | "quiz" | "result">("landing");
  const [showSettings, setShowSettings] = useState(false);
  const [settings, setSettings] = useState<GameSettings>(() => { try { return { ...defaultSettings, ...JSON.parse(localStorage.getItem("iq-arena-settings") || "{}") }; } catch { return defaultSettings; } });
  const [profile, setProfile] = useState<PlayerProfile>(() => { try { return { ...defaultProfile, ...JSON.parse(localStorage.getItem("iq-arena-profile") || "{}") }; } catch { return defaultProfile; } });
  const [session, setSession] = useState<Question[]>([]);
  const [result, setResult] = useState({ score: 0, answers: [] as number[], elapsed: 0 });
  const startSession = (nextProfile = profile, nextSettings = settings) => { const difficultySet = nextSettings.difficulty === "all" ? questionBank : questionBank.filter((question) => nextSettings.difficulty === "advanced" ? question.difficulty === "صعب" || question.difficulty === "خبير" : question.difficulty !== "خبير"); const source = difficultySet.length >= nextSettings.questionCount ? difficultySet : questionBank; const picked = shuffle(source).slice(0, nextSettings.questionCount).map((question) => ({ ...question, timeLimit: nextSettings.timeMode })); setSession(picked); setScreen("quiz"); setShowSettings(false); if (nextSettings.saveProgress) { localStorage.setItem("iq-arena-settings", JSON.stringify(nextSettings)); localStorage.setItem("iq-arena-profile", JSON.stringify(nextProfile)); } };
  const saveAndStart = (nextProfile: PlayerProfile, nextSettings: GameSettings) => { setProfile({ ...nextProfile, name: nextProfile.name.trim() }); setSettings(nextSettings); startSession({ ...nextProfile, name: nextProfile.name.trim() }, nextSettings); };
  const finish = (score: number, answers: number[], elapsed: number) => { setResult({ score, answers, elapsed }); setScreen("result"); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const restart = () => { setScreen("landing"); setShowSettings(true); window.scrollTo({ top: 0, behavior: "smooth" }); };
  useEffect(() => { const params = new URLSearchParams(window.location.search); if (params.has("result")) { setProfile({ name: "نور", age: "27" }); setResult({ score: 9, answers: [], elapsed: 286 }); setSession(shuffle(questionBank).slice(0, 12)); setScreen("result"); return; } if (params.has("demo")) { const timer = window.setTimeout(() => startSession(), 700); return () => window.clearTimeout(timer); } }, []);
  return <div dir="rtl" className={`app-frame ${settings.motion ? "" : "motion-off"}`}>{screen === "landing" && <Landing profile={profile} settings={settings} onStart={() => setShowSettings(true)} onOpenSettings={() => setShowSettings(true)} />}{screen === "quiz" && <Quiz session={session} profile={profile} settings={settings} onFinish={finish} />}{screen === "result" && <Result {...result} profile={profile} sessionLength={session.length || settings.questionCount} onRestart={restart} />}{showSettings && <SettingsPanel profile={profile} settings={settings} onClose={() => setShowSettings(false)} onSave={saveAndStart} />}</div>;
}
